// 6. ดึงสถิติย้อนหลัง 24 ชม. จาก InfluxDB (Flux query) แล้วสรุปเป็นตัวเลข
const url = `${$env.INFLUX_URL}/api/v2/query?org=${encodeURIComponent($env.INFLUX_ORG)}`;
const bucket = $env.INFLUX_BUCKET;

async function flux(query) {
  const csv = await this.helpers.httpRequest({
    method: 'POST', url, body: query, json: false,
    headers: {
      Authorization: `Token ${$env.INFLUX_TOKEN}`,
      'Content-Type': 'application/vnd.flux',
      Accept: 'application/csv',
    },
  });
  return parseCsv(String(csv));
}

// InfluxDB ตอบเป็น annotated CSV: หลายตารางคั่นด้วยบรรทัดว่าง แต่ละตารางมีหัวคอลัมน์ของตัวเอง
function parseCsv(text) {
  const rows = [];
  let header = null;
  for (const raw of text.split(/\r?\n/)) {
    if (!raw.trim()) { header = null; continue; }
    const cells = splitLine(raw);
    if (!header) { header = cells; continue; }
    const row = {};
    header.forEach((h, i) => { row[h] = cells[i]; });
    rows.push(row);
  }
  return rows;
}

function splitLine(line) {
  const out = []; let cur = ''; let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quoted) {
      if (ch === '"' && line[i + 1] === '"') { cur += '"'; i++; }
      else if (ch === '"') quoted = false;
      else cur += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { out.push(cur); cur = ''; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const base = `from(bucket: "${bucket}") |> range(start: -24h)`;

const sums = await flux.call(this, `${base}
  |> filter(fn: (r) => r._measurement == "golf_event")
  |> filter(fn: (r) => r._field == "golf_count" or r._field == "reject_count" or r._field == "white" or r._field == "neon" or r._field == "pink")
  |> group(columns: ["_field"]) |> sum()`);

const counts = await flux.call(this, `${base}
  |> filter(fn: (r) => r._measurement == "golf_event" and r._field == "golf_count")
  |> group(columns: ["kind"]) |> count()`);

const status = await flux.call(this, `${base}
  |> filter(fn: (r) => r._measurement == "golf_status" and (r._field == "golf_count" or r._field == "fps"))
  |> group(columns: ["_field"])
  |> reduce(identity: {n: 0, mx: 0.0, total: 0.0},
            fn: (r, accumulator) => ({n: accumulator.n + 1,
                                      mx: if float(v: r._value) > accumulator.mx then float(v: r._value) else accumulator.mx,
                                      total: accumulator.total + float(v: r._value)}))`);

const recent = await flux.call(this, `${base}
  |> filter(fn: (r) => r._measurement == "golf_event" and r._field == "message" and r.kind != "golf")
  |> group() |> sort(columns: ["_time"], desc: true) |> limit(n: 10)`);

const sum = f => Number((sums.find(r => r._field === f) || {})._value || 0);
const events = {};
for (const r of counts) events[r.kind] = Number(r._value);
const st = f => status.find(r => r._field === f) || {};

const stats = {
  date: new Date().toLocaleDateString('th-TH', { timeZone: $env.TZ || 'Asia/Bangkok', dateStyle: 'long' }),
  events_total: Object.values(events).reduce((a, b) => a + b, 0),
  events_golf_only: events.golf || 0,
  events_reject: events.reject || 0,
  events_mixed: events.mixed || 0,
  golf_seen: sum('golf_count'),
  white: sum('white'), neon: sum('neon'), pink: sum('pink'),
  rejects_seen: sum('reject_count'),
  max_golf_at_once: Number(st('golf_count').mx || 0),
  camera_online_minutes: Math.round(Number(st('golf_count').n || 0) / 60),
  avg_fps: st('fps').n ? Math.round(10 * st('fps').total / st('fps').n) / 10 : 0,
  // เวลาจาก InfluxDB เป็น UTC เสมอ ต้องแปลงเป็นเวลาไทยก่อนแสดง
  recent_rejects: recent.map(r => `${new Date(r._time).toLocaleTimeString('th-TH', { timeZone: $env.TZ || 'Asia/Bangkok', hour12: false })} ${r._value}`),
};
return [{ json: stats }];

// AI สรุปรายงานประจำวัน
//   มี GEMINI_API_KEY    -> ใช้ Google Gemini
//   มี ANTHROPIC_API_KEY -> ใช้ Claude
//   ไม่มีทั้งคู่          -> สรุปแบบตัวเลขธรรมดา (ระบบยังทำงานได้)
const s = $input.first().json;

const plain = [
  `📊 รายงานระบบคัดแยกลูกกอล์ฟ ${s.date}`,
  `กล้องออนไลน์ ~${s.camera_online_minutes} นาที (FPS เฉลี่ย ${s.avg_fps})`,
  `เหตุการณ์ทั้งหมด ${s.events_total} ครั้ง: ปกติ ${s.events_golf_only} / แปลกปลอม ${s.events_reject} / ปนกัน ${s.events_mixed}`,
  `ลูกกอล์ฟที่ตรวจพบ ${s.golf_seen} ครั้ง (ขาว ${s.white} / นีออน ${s.neon} / ชมพู ${s.pink})`,
  `สิ่งแปลกปลอมที่ถูกปฏิเสธ ${s.rejects_seen} ชิ้น  |  เห็นพร้อมกันมากสุด ${s.max_golf_at_once} ลูก`,
  s.recent_rejects.length ? `ล่าสุด:\n- ${s.recent_rejects.slice(0, 5).join('\n- ')}` : 'ไม่พบสิ่งแปลกปลอมใน 24 ชม.',
].join('\n');

const system = 'คุณเป็นวิศวกรควบคุมคุณภาพในสายการผลิตที่ใช้กล้องคัดแยกลูกกอล์ฟ ' +
  'เขียนรายงานประจำวันภาษาไทยสั้น กระชับ สำหรับส่งทาง Telegram ' +
  '(ไม่เกิน 12 บรรทัด ใช้อีโมจิได้เล็กน้อย เป็นข้อความธรรมดา ห้ามใช้ Markdown เช่น ** # หรือตาราง) ' +
  'สรุปตัวเลขสำคัญ ชี้จุดผิดปกติ และแนะนำสิ่งที่ควรทำต่อ 1-2 ข้อ ' +
  'ห้ามแต่งตัวเลขที่ไม่มีในข้อมูล';
const prompt = `ข้อมูลสถิติ 24 ชั่วโมงล่าสุด (JSON):\n${JSON.stringify(s, null, 2)}`;

// Code node ของ n8n ส่ง error ออกมาแค่ข้อความ "Request failed with status code 404"
// จึงต้องแกะรหัสจากข้อความด้วย ไม่ใช่ดูแค่ฟิลด์ตัวเลข
const httpStatus = err => String(err.httpCode || err.statusCode || (err.response && err.response.status) ||
  ((String(err.message).match(/status code (\d{3})/) || [])[1]) || '');

// ---------- Google Gemini ----------
async function askGemini(helpers) {
  const key = $env.GEMINI_API_KEY;
  const base = 'https://generativelanguage.googleapis.com/v1beta';
  const body = {
    system_instruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    generationConfig: { maxOutputTokens: 4096 },
  };
  // ตั้งเวลาหมดไว้ด้วย - ทดสอบ 28 ต.ค. 2026 รุ่น gemini-3.8-flash / gemini-flash-latest ค้างเกิน 60 วินาที
  const call = model => helpers.httpRequest({
    method: 'POST', url: `${base}/models/${model}:generateContent`,
    headers: { 'x-goog-api-key': key, 'Content-Type': 'application/json' },
    body, json: true, timeout: 45000,
  });

  // รุ่นสำรองเผื่อรุ่นใน .env เลิกให้บริการ (404) / ค้าง / ล่ม:
  // ถาม Google ว่ามี gemini-X.Y-flash อะไรบ้าง เรียงเลขรุ่นจากสูงไปต่ำ (ไม่เอา lite / preview / tts / image)
  async function backupModels() {
    const list = await helpers.httpRequest({
      method: 'GET', url: `${base}/models?pageSize=200`, headers: { 'x-goog-api-key': key }, json: true,
    });
    const ver = n => (n.match(/^gemini-(\d+(?:\.\d+)?)-flash$/) || [])[1];
    return (list.models || [])
      .filter(m => (m.supportedGenerationMethods || []).includes('generateContent'))
      .map(m => m.name.replace(/^models\//, ''))
      .filter(ver)
      .sort((a, b) => parseFloat(ver(b)) - parseFloat(ver(a)));
  }

  const first = ($env.GEMINI_MODEL || 'gemini-3.5-flash').replace(/^models\//, '');
  const tried = [];
  let candidates = [first];
  let lastErr;
  while (candidates.length && tried.length < 3) {
    const model = candidates.shift();
    if (tried.includes(model)) continue;
    tried.push(model);
    try {
      const res = await call(model);
      const cand = (res.candidates || [])[0];
      const text = cand && cand.content ? (cand.content.parts || []).map(p => p.text || '').join('').trim() : '';
      const blocked = (res.promptFeedback && res.promptFeedback.blockReason) || (cand && cand.finishReason === 'SAFETY');
      return { text: blocked ? '' : text, model, why: blocked ? 'blocked' : (cand && cand.finishReason) };
    } catch (err) {
      lastErr = err;
      // key ผิด / ไม่มีสิทธิ์ / โควตาหมด -> เปลี่ยนรุ่นก็ไม่ช่วย หยุดเลย
      if (['400', '401', '403', '429'].includes(httpStatus(err))) throw err;
      if (tried.length === 1) candidates = await backupModels().catch(() => []);
    }
  }
  lastErr.message = `ลองแล้ว ${tried.join(', ')}: ${lastErr.message}`;
  throw lastErr;
}

// ---------- Claude ----------
async function askClaude(helpers) {
  const model = $env.AI_MODEL || 'claude-opus-5-5';
  const body = {
    model, max_tokens: 4000, output_config: { effort: 'low' }, system,
    messages: [{ role: 'user', content: prompt }],
  };
  const headers = {
    'x-api-key': $env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json',
  };
  // ถ้าโมเดลหลักปฏิเสธคำขอ ให้ API สลับไปใช้โมเดลสำรองให้เองในคำขอเดียวกัน
  if (/^claude-(opus-5|fable-5|sonnet-5-5)/.test(model)) {
    body.fallbacks = 'default';
    headers['anthropic-beta'] = 'server-side-fallback-2026-07-01';
  }
  const res = await helpers.httpRequest({
    method: 'POST', url: 'https://api.anthropic.com/v1/messages', headers, body, json: true,
  });
  const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
  return { text: res.stop_reason === 'refusal' ? '' : text, model: res.model, why: res.stop_reason };
}

const provider = $env.GEMINI_API_KEY ? 'gemini' : ($env.ANTHROPIC_API_KEY ? 'claude' : null);
if (!provider) {
  return [{ json: { report: plain, ai: false, note: 'ไม่ได้ตั้ง GEMINI_API_KEY / ANTHROPIC_API_KEY จึงส่งสรุปแบบไม่ใช้ AI' } }];
}

try {
  const r = provider === 'gemini' ? await askGemini(this.helpers) : await askClaude(this.helpers);
  if (!r.text) {
    return [{ json: { report: plain, ai: false, note: `${provider} ไม่ตอบ (${r.why})` } }];
  }
  // Telegram ส่งแบบข้อความธรรมดา เครื่องหมาย Markdown จะโผล่ให้เห็นตรง ๆ จึงตัดทิ้งเผื่อ AI ไม่ทำตามคำสั่ง
  const clean = r.text.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^#+\s*/gm, '');
  return [{ json: { report: `🤖 ${clean}`, ai: true, provider, model: r.model } }];
} catch (err) {
  // API ล่ม / key ผิด / เน็ตหลุด -> ยังส่งรายงานแบบธรรมดาได้
  return [{ json: { report: plain, ai: false, note: `เรียก ${provider} ไม่สำเร็จ (${httpStatus(err) || '-'}): ${err.message}` } }];
}

// 7. ส่งรายงานสรุปประจำวันไปที่ Telegram
const { report, note } = $input.first().json;
const token = $env.TELEGRAM_TOKEN;
const chatId = $env.TELEGRAM_CHAT_ID;
if (!token || !chatId) {
  return [{ json: { sent: false, reason: 'ยังไม่ได้ตั้ง TELEGRAM_TOKEN / TELEGRAM_CHAT_ID ใน .env', report, note } }];
}
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${token}/sendMessage`,
  body: { chat_id: chatId, text: report },
  json: true,
});
return [{ json: { sent: res.ok === true, message_id: res.result && res.result.message_id, report, note } }];
